 await page.goto(`http://127.0.0.1:${server.address().port}/surface-edge.html`);await page.waitForFunction(()=>window.haganeSurfaceEdge?.ready);
 function checkLiftedEdge(data){
  assert.equal(data.brep.edges,1);assert.equal(data.brep.closed,false);assert.deepEqual(data.brep.edge_vertices,[0,1]);assert.deepEqual(data.brep.edge_range,[0,1]);assert.deepEqual(data.pcurve_origin,data.start);assert.equal(data.parameters[0],0);assert.equal(data.parameters.at(-1),1);assert.equal(data.samples.length,data.parameters.length*3);assert.equal(data.error_bounds.length,data.parameters.length-1);
  const exact=t=>{const [u,v]=data.start.map((x,i)=>x+t*data.pcurve_direction[i]);if(data.crease){if(u<=0.5){const s=2*u,f=data.weight*s/(1-s+data.weight*s);return [-40+40*f,60*v-30,data.height*f];}const s=2*u-1,f=s/(data.weight*(1-s)+s);return [40*f,60*v-30,data.height*(1-f)];}const a=4*u*(1-u)*v*(1-v),d=1+(data.weight-1)*a;return [(80*u-40)/d,(60*v-30)/d,data.height*data.weight*a/d];},near=(a,b)=>a.forEach((x,i)=>assert.ok(Math.abs(x-b[i])<1e-10));near(data.pcurve_direction,data.end.map((x,i)=>x-data.start[i]));near(data.brep.vertices[0],exact(0));near(data.brep.vertices[1],exact(1));near(data.point,exact(0.5));data.parameters.forEach((t,i)=>near(data.samples.slice(i*3,i*3+3),exact(t)));
  for(let i=0;i<data.error_bounds.length;i++){const bound=data.error_bounds[i],start=data.parameters[i],end=data.parameters[i+1],a=data.samples.slice(i*3,i*3+3),b=data.samples.slice(i*3+3,i*3+6),d=b.map((x,j)=>x-a[j]),length2=d.reduce((s,x)=>s+x*x,0);assert.ok(start<end&&bound>0&&bound<=data.edge_error);for(let j=0;j<=16;j++){const p=exact(start+(end-start)*j/16),s=length2?Math.max(0,Math.min(1,d.reduce((sum,x,k)=>sum+x*(p[k]-a[k]),0)/length2)):0;assert.ok(Math.hypot(...p.map((x,k)=>x-a[k]-s*d[k]))<=bound+1e-10);}}
 }
